function primaryMaterial(t){return taskMaterials(t)[0]}
function dayTaskCard(t){const r=primaryMaterial(t),done=!!state.dayChecks[t.id];return`<article class="day-task ${done?'done':''}"><div class="day-task-top"><label class="day-check"><input type="checkbox" data-daily-check="${t.id}" ${done?'checked':''} aria-label="完成 ${escapeHTML(t.title)}"><span class="sr-only">完成本块</span></label><button class="task-open" data-open-task="${t.id}"><span class="task-name">${escapeHTML(t.title)}</span><span class="task-sub">${PLAN.categories.find(x=>x.key===t.cat)?.name||'完整模拟'} · ${t.min}分钟 · 点击看步骤、产物与复测</span></button><span class="time-token">${t.min}<small>min</small></span></div><div class="task-links"><a href="${escapeHTML(r.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(r.label)}</a><button data-open-task="${t.id}" class="task-detail-btn">看具体做法</button></div>${r.key==='bc'||r.key==='familiar'?'<p class="task-warning">入口可用；开始前确认一套完整未见材料，短样题不能替代基线。</p>':''}</article>`}
function dayCards(w){const ds=dailyPlan(w);return`<div class="day-picker" aria-label="选择一天">${ds.map((tasks,i)=>{const min=tasks.reduce((a,t)=>a+t.min,0),done=tasks.filter(t=>state.dayChecks[t.id]).length;return`<button data-select-day="${i}" class="${(selectedDay??dayIndexFor(w))===i?'active':''}" aria-pressed="${(selectedDay??dayIndexFor(w))===i}"><small>DAY ${i+1}</small><b>${dayLabel(w,i)}</b><span>${min?min+'分钟':'休息'}${min?' · '+done+'/'+tasks.length:''}</span></button>`}).join('')}</div>`}
function dayWorkspace(w,d){const list=dailyPlan(w)[d],info=weekInfo(w);return`<div class="panel-title"><div><span class="eyebrow">${dayDate(w,d)} / DAY ${d+1}</span><h2>${d===6?'今天留给生活。':`今天的${list.length}个学习块`}</h2><p>${d===6?'休息也是计划的一部分，不把欠账全部压到今天。':`共${list.reduce((a,t)=>a+t.min,0)}分钟。先点材料，再看做法；所有碎片块已计入。`}</p></div>${badge('W'+String(w).padStart(2,'0'))}</div>${list.length?list.map(dayTaskCard).join(''):'<div class="rest-day"><span>OFF DAY</span><h3>关掉任务清单，去做别的。</h3><p>作品集、运动、朋友或单纯休息。若本周错过重要诊断，重新排期，而不是为了补打卡熬夜。</p></div>'}<div class="hint">本周重点：${escapeHTML(info.title)}。${escapeHTML(info.gate)}</div>`}
function dayBudgetBlock(w){const st=dailyStats(w),sums={};st.tasks.forEach(t=>sums[t.cat]=(sums[t.cat]||0)+t.min);return`<div class="budget-bar">${Object.entries(sums).map(([k,v])=>`<span style="width:${v/st.total*100}%;background:${PLAN.categories.find(c=>c.key===k)?.color||'#263450'}"></span>`).join('')}</div><div class="budget-legend">${Object.entries(sums).map(([k,v])=>`<span><i style="background:${PLAN.categories.find(c=>c.key===k)?.color||'#263450'}"></i>${PLAN.categories.find(c=>c.key===k)?.name||'联考'} ${v}分钟</span>`).join('')}</div><p class="inline-note">${MOCK_WEEKS.includes(w)&&w!==1&&state.settings.mode!=='busy'?'联考180分钟已含听读写；其他为专项/反馈，合计仍不变。':w>16?'机动区为每天最多30分钟的可选轻复习；规划考试日及之后不安排任务。':(state.settings.mode==='busy'&&w!==1?'忙周词汇60分钟=4天×(手机10+纸书5)，已经包含在360分钟内。':'词汇75分钟是5个主学习日×(手机10+纸书5)，不是7天额外打卡。')}${w===1?'首周固定630分钟，先完成基线。':''}</p>`}
function dailyTodayHTML(){const w=selectedWeek||currentWeek(),d=selectedDay??dayIndexFor(w),st=dailyStats(w),remaining=3527-state.learning.seen;return`${pageTitle('TODAY, WITH THE MATERIALS','今天做什么，点开就知道。','每块都写清材料、步骤、完成标准与下次复测。先完成高质量产物，再勾选。',badge('Academic · 每周10–12h'))}<div class="daily-top-grid"><section class="mission compact"><div><span class="eyebrow">W${String(w).padStart(2,'0')} / ${dateLabel(state.settings.start)}—${dateLabel(deadline())}</span><h2>${weekInfo(w).title}</h2><p>本周主题：${DAILY_TOPICS[Math.min(w-1,15)]}。日期和目标可在设置中修改。</p></div><div class="mission-number">${state.settings.goal}<sup>+</sup></div><div class="mission-bottom"><span>本周 ${st.minutes} / ${st.total} 分钟</span><span>${st.done} / ${st.count} 块完成</span></div></section><section class="panel vocab-summary"><div class="panel-title"><div><span class="eyebrow">BAICIZHAN × PAPER</span><h2>沿用你的词汇习惯</h2></div>${badge('手动记录','neutral')}</div><div class="vocab-progress"><strong>${state.learning.seen}</strong><span>/ 3527 条首轮进度</span></div><div class="progress"><span style="width:${state.learning.seen/3527*100}%"></span></div><p class="inline-note">剩${remaining}条 · ${(state.learning.seen/3527*100).toFixed(1)}%是覆盖进度，包含跳过词，不是掌握率。</p><button class="text-button" data-go="vocab">查看纸书推荐、复习安排与错词</button></section></div><div class="day-toolbar"><div><span class="eyebrow">DAY-BY-DAY PLAN</span><h2>选一天，展开每个学习块</h2></div><div class="actions" style="margin:0"><button class="secondary" data-action="back-today">回到今天</button><button class="soft" data-go="roadmap">查看16周路线</button></div></div>${dayCards(w)}<div class="daily-grid"><section class="panel">${dayWorkspace(w,d)}</section><div class="stack"><section class="panel"><h2>这周的时间账</h2>${dayBudgetBlock(w)}<div class="hint">${state.settings.mode==='busy'?'本周为6小时应急版本，保留闭环但不具有与标准周相同的冲8预期。':'单词复习替换原来刷手机的时间，但仍计入总预算；不暗加到10.5小时以外。'}</div></section><section class="panel"><span class="eyebrow">QUICK LINKS</span><h2>要用的东西，就在这里</h2><div class="quick-links">${[['lpdf','听力：题目 + 录音入口 + 答案'],['rpdf','阅读：判断 / 匹配 / 填空'],['wpdf','写作：题目 + 范文考官评语'],['spdf','口语：Part 1–3样题'],['book','纸书：《雅思词汇真经》']].map(([k,label])=>`<a href="${escapeHTML(STUDY_RESOURCES[k].url)}" target="_blank" rel="noopener noreferrer">${label}<small>${STUDY_RESOURCES[k].type}</small></a>`).join('')}</div><p class="inline-note">题型样题有数量上限。整套模拟先备未见合法试卷；不把重复样题当新题分数。</p></section><section class="panel"><h2>忘了，也算有用的信息。</h2><p style="margin-top:12px;font-size:.875rem">先遮答案回忆、及时核对、隔开再测。忘得多就降低新词量；成功回忆后才拉长间隔。</p><a class="source-mini" href="${STUDY_RESOURCES.distributed.url}" target="_blank" rel="noopener noreferrer">学习方法研究依据</a><p class="inline-note">研究支持方法方向，不证明本计划的分钟数或固定复习间隔最优。</p></section></div></div>${legacyProgressHTML(w)}`}
function legacyProgressHTML(w){const old=taskDefs(w),count=old.filter(t=>state.checks[t.id]).length;if(!count)return'';return`<details class="legacy-record"><summary>旧版周打卡记录仍保留 · ${count}/${old.length}项</summary><div class="detail-body"><p>新版按日期与具体学习块记录；旧记录没有清除，也没有自动换算成新任务完成。可继续查看原始勾选，JSON备份同时保留。</p>${old.map(taskHTML).join('')}</div></details>`}
function dailyRoadmapHTML(){const w=selectedWeek,d=selectedDay??dayIndexFor(w),st=dailyStats(w),inf=weekInfo(w),span=dayDiff(state.settings.start,deadline());return`${pageTitle('16 WEEKS, 112 DATED DAYS','四个月路线，落实到每一天。','每周重点不同，每天材料与执行卡都可点开。样题重练与未见整套测量分开记录。',modeSwitch())}<div class="calendar-strip"><span>${state.settings.start} 至 <b>${deadline()}</b></span><span><b>${span}天 / ${(span/7).toFixed(1)}周</b></span><span>16周训练 + <b>${span-112}天考前机动</b></span></div><div class="phase-grid" style="margin-top:20px">${PLAN.phases.map((p,i)=>`<div class="phase ${Math.min(3,Math.floor((w-1)/4))===i?'current':''}"><small>${p.weeks}</small><h3>${p.name}</h3><p>${p.focus}</p></div>`).join('')}</div><div class="week-tabs">${Array.from({length:totalWeeks()},(_,i)=>`<button data-daily-week="${i+1}" class="${w===i+1?'active':''}" aria-pressed="${w===i+1}">W${String(i+1).padStart(2,'0')}${i>=16?' 机动':''}</button>`).join('')}</div><section class="panel"><div class="panel-title"><div><span class="eyebrow">WEEK ${String(w).padStart(2,'0')}</span><h2>${inf.title}</h2><p>本周主题：${DAILY_TOPICS[Math.min(w-1,15)]}</p></div>${badge(`${st.minutes}/${st.total}分钟`)}</div><div class="four-focus">${['L','R','W','S'].map((k,i)=>`<div><b>${PLAN.categories[i].name}</b><p>${inf[k]}</p></div>`).join('')}</div><div class="hint">${inf.gate}</div>${MOCK_WEEKS.includes(w)&&state.settings.mode!=='busy'?'<div class="hint warning">模拟周：Day6预留完整180分钟听读写；材料必须是一套未见合法卷。若只有已做样题，就改记重练，不能制造“新题达标”证据。</div>':''}${w>16?'<div class="hint warning">机动区任务仅供选择，最后一周不满7天；规划考试日及之后的日期不再安排强制训练。</div>':''}</section>${dayCards(w)}<div class="daily-grid"><section class="panel">${dayWorkspace(w,d)}</section><div class="stack"><section class="panel"><h2>本周产出</h2><ul class="outputs">${inf.deliver.map(x=>`<li>${x}</li>`).join('')}</ul>${dayBudgetBlock(w)}</section><section class="panel"><h2>周复盘</h2><label class="field" style="margin-top:13px">证据 + 下周两个优先项<textarea id="week-note" maxlength="5000" placeholder="例：Heading错在段落功能；写作原因解释不足。下周分别用新题与重写验证。">${escapeHTML(state.notes['w'+w]||'')}</textarea></label><button class="soft" data-action="save-week-note">保存这周复盘</button><p class="inline-note">原有周复盘和成绩保留；切换模式不删除其他模式记录。</p></section><section class="panel"><h2>完整卷先备好</h2><p class="inline-note">基线和W4/8/12/14/16要用未见材料，不能仅靠有限的免费题型样例循环评分。Cambridge20只有4套；自有其他正版卷或官方账户内可用材料可补足。</p><div class="quick-links"><a href="${STUDY_RESOURCES.c20.url}" target="_blank" rel="noopener noreferrer">Cambridge20官方信息 <small>4套 / 需合法持有</small></a><a href="${STUDY_RESOURCES.ready.url}" target="_blank" rel="noopener noreferrer">IELTS Ready免费注册资源 <small>账户内实际卷数需确认</small></a></div></section></div></div>${legacyProgressHTML(w)}<div class="actions"><button class="secondary" data-action="toggle-week-days">${showAllDays?'收起整周清单':'展开整周每日概览'}</button><button class="secondary" data-action="print-plan">打开完整打印计划</button></div>${showAllDays?`<div class="two-col" style="margin-top:20px">${dailyPlan(w).map((ts,i)=>`<section class="panel"><h3>${dayLabel(w,i)} · ${ts.reduce((a,t)=>a+t.min,0)}分钟</h3>${ts.length?ts.map(dayTaskCard).join(''):'<p class="inline-note">免备考，休息。</p>'}</section>`).join('')}</div>`:''}`}
function taskById(id){if(typeof id!=='string')return null;const m=id.match(/^dw(\d+)_(normal|busy|stretch)_d([0-6])_[A-Za-z0-9]+$/);if(!m)return null;const w=Number(m[1]);if(w<1||w>totalWeeks())return null;return dailyPlan(w,m[2])[Number(m[3])].find(t=>t.id===id)||null}
function openTask(id){const t=taskById(id);if(!t)return toast('没有找到这项任务。');openTaskId=id;const r=taskRecipe(t),sum=r.steps.reduce((a,s)=>a+s.minutes,0);$('#task-detail').innerHTML=`<header class="task-dialog-header"><div><span class="eyebrow">${dayDate(t.w,t.d)} · W${t.w} / DAY ${t.d+1} · ${t.min} MIN</span><h2>${escapeHTML(t.title)}</h2></div><button class="quiet" data-action="close-task" aria-label="关闭任务详情">关闭</button></header><div class="task-dialog-body"><p class="task-objective">${escapeHTML(r.objective)}</p><section class="detail-section"><div class="detail-section-title"><span>01</span><h3>先打开今天的材料</h3></div><div class="material-links">${r.materials.map((x,i)=>`<a class="material-link ${i===0?'primary':''}" href="${escapeHTML(x.url)}" target="_blank" rel="noopener noreferrer"><b>${escapeHTML(x.label)}</b><span>${escapeHTML(x.type)} · ${escapeHTML(x.note)}</span></a>`).join('')}</div>${['lpractice','lreview','rpractice','rreview','wtask1'].includes(t.kind)?'<p class="inline-note">官方样题数量有限：若做过，本次记重练；要验证新题迁移，请用合法自有的同题型未见材料并记卷号。本站不把同一PDF算成多套新卷。</p>':''}${['ltest','rtest','mock'].includes(t.kind)?`<div class="hint warning">这块需要完整未见材料。官方题型PDF只有短题组，不能冒充完整40题；先在官方机考熟悉测试或自己的正版卷中选定，再记录下面的来源。IELTS Ready可能需要免费注册，本站未替你注册或核验账户内卷数。</div><label class="field" style="margin-top:13px">本次实际材料（必须先选好）<input id="task-material" maxlength="300" value="${escapeHTML(state.dailyNotes['material_w'+t.w]||'')}" placeholder="例：Cambridge20 Academic Test2；未见 / 已做过"></label>`:''}</section><section class="detail-section"><div class="detail-section-title"><span>02</span><h3>按这个顺序做 · 共${sum}分钟</h3></div><ol class="execution-steps">${r.steps.map(s=>`<li><b>${s.minutes}′</b><p>${escapeHTML(s.text)}</p></li>`).join('')}</ol></section><div class="detail-pair"><section><span class="eyebrow">完成标准</span><p>${escapeHTML(r.output)}</p></section><section><span class="eyebrow">错了怎么复盘 / 下次怎么测</span><p>${escapeHTML(r.review)}</p></section></div><details><summary>今天真的很忙，最小可行版本是什么？</summary><div class="detail-body">${escapeHTML(r.busy)}<p>只做缩减版时，在笔记写清完成范围，不把整块勾成完成；或切换整周忙周计划。</p></div></details><label class="field">留一句产物或错因（可选）<textarea id="task-note" maxlength="2000" placeholder="题号/文件名/录音时间戳/原句→修改/下一次检查项">${escapeHTML(state.dailyNotes[t.id]||'')}</textarea></label><div class="hint"><b>下一步：</b>${escapeHTML(r.next)}</div></div><footer class="task-dialog-footer"><button class="secondary" data-action="save-task-note">保存笔记</button><button class="${state.dayChecks[id]?'secondary':''}" data-action="complete-open-task">${state.dayChecks[id]?'取消完成标记':'产物已完成，勾选本块'}</button><button class="soft" data-action="next-task">下一块任务</button></footer>`;const dlg=$('#task-dialog');if(!dlg.open)dlg.showModal()}
function saveTaskNote(){if(!openTaskId)return false;state.dailyNotes[openTaskId]=$('#task-note')?.value||'';const t=taskById(openTaskId),m=$('#task-material');if(m&&t)state.dailyNotes['material_w'+t.w]=m.value;return save()}
function vocabHTML(){const l=state.learning,remain=3527-l.seen,due=l.entries.filter(x=>x.due<=today());return`${pageTitle('YOUR VOCABULARY SYSTEM','百词斩 + 纸书，继续做熟。','保留已经建立的习惯。先收尾这一轮，再让主动回忆和错词复测成为主线。',badge('不接入App · 本机手动记录'))}<div class="two-col"><section class="panel"><span class="eyebrow">FIRST PASS, NOT MASTERY</span><h2>首轮覆盖进度</h2><div class="vocab-progress large"><strong>${l.seen}</strong><span>/ 3527</span></div><div class="progress"><span style="width:${l.seen/3527*100}%"></span></div><p style="margin-top:12px">剩${remain}条；${(l.seen/3527*100).toFixed(1)}%包含以前词库自动跳过的条目，不能解释为掌握率。</p><form id="vocab-settings-form"><div class="form-row"><label class="field">App实际已覆盖条目<input name="seen" type="number" min="0" max="3527" step="1" value="${l.seen}" required></label><label class="field">单次新词上限（可减到0执行）<input name="newLimit" type="number" min="1" max="50" step="1" value="${l.newLimit}" required></label></div><label class="field">当前阶段<select name="phase"><option value="firstpass" ${l.phase==='firstpass'?'selected':''}>首轮收尾：到期复习优先，余时新词</option><option value="review" ${l.phase==='review'?'selected':''}>首轮后：把新词时间换成旧词/错词回忆</option></select></label><button type="submit" style="margin-top:15px">保存词汇进度</button></form><p class="inline-note">按每次最多${l.newLimit}条，剩余至少约${Math.ceil(remain/l.newLimit)}个有新词的学习日；若到期复习多就延长。网站不替你加计数，也不与百词斩同步。</p></section><section class="panel"><h2>每个主学习日15分钟</h2><div class="numbered" style="margin-top:18px"><div class="step"><div><h3>手机10分钟：先回忆，再揭答案</h3><p>先做到期复习，遮图片/选项想词义或拼写；余下时间才加新词，最多${l.newLimit}条不是必须赶完。替换原来刷手机的时间。</p></div></div><div class="step"><div><h3>纸书5分钟：只处理真困难</h3><p>最多3个错词：遮义回忆、必要时听音拼写，选1–2个搭配造句。不要整页抄写，也不另开第二本大词表。</p></div></div><div class="step"><div><h3>周复盘：抽查自动跳过的词</h3><p>随机20词，脱离图片/选项测词义；挑5个加测发音/拼写/搭配。分别记表现，不把App计数当分数。</p></div></div></div><div class="hint">5×15 = 75分钟，已放进630分钟标准周；Day6词抽测包含在周复盘中，Day7休息。不是每天额外15分钟。</div></section></div><div class="section-heading"><h2>纸质单词书：先选与你现有词库相配的一本</h2><p>如果已经有，就不用重复购买。</p></div><div class="two-col"><article class="panel book-card"><span class="eyebrow">主推荐 / 延续已有投入</span><h2>《雅思词汇真经》</h2><p class="book-meta">刘洪波 · 外语教学与研究出版社<br>ISBN 9787521304558 · 2018-11</p><p>和你正在学的词库方向一致，适合按词群查语境、遮挡回忆、标困难词。App3527与纸书词条数不保证一一对应，不必强求页码完全同步。</p><div class="actions"><a class="button-link" href="${STUDY_RESOURCES.book.url}" target="_blank" rel="noopener noreferrer">查看新华书店书页</a><a href="${STUDY_RESOURCES.bookcheck.url}" target="_blank" rel="noopener noreferrer">核对权威书目</a></div></article><article class="panel book-card"><span class="eyebrow">可选补充 / 暂不必同时开</span><h2>IELTS Vocabulary for<br>Bands 6.5 and above</h2><p class="book-meta">Pauline Cullen · Cambridge University Press<br>ISBN 9781108907194 · 2021</p><p>原名Cambridge Vocabulary for IELTS Advanced。若第一轮后仍明显缺语境、搭配和可用表达，可以选章补充；不要与《真经》同时全量推进。</p><div class="actions"><a class="button-link secondary-link" href="${STUDY_RESOURCES.cullen.url}" target="_blank" rel="noopener noreferrer">查看出版社书页</a></div><p class="inline-note">没有核实你当地的即时价格、库存或促销；未进行购买。</p></article></div><div class="section-heading"><h2>纸上错词，也可以在这里留索引</h2><p>已收${l.entries.length}条 · 今天到期${due.length}条</p></div><div class="two-col"><section class="panel"><h2>添加一条真错词</h2><form id="paper-word-form"><div class="form-row"><label class="field">词 / 短语<input name="term" maxlength="120" required placeholder="例：accommodation"></label><label class="field">下次复测日<input name="due" type="date" value="${plusDays(today(),1)}" required></label></div><label class="field">词义 + 这次错在哪里<input name="meaning" maxlength="600" placeholder="例：住宿；听懂但漏写一个m"></label><label class="field" style="margin-top:13px">搭配或自己的例句<textarea name="example" maxlength="1000" placeholder="写一条短而准确的搭配/例句，不抄整页。"></textarea></label><button type="submit">保存错词</button></form></section><section class="panel"><h2>到期回忆</h2><p class="inline-note">先遮住答案自己回忆，再展开核对。这里不主动提醒、不上传App。按钮会改变这条词的下次日期。</p>${due.length?due.slice(0,20).map(x=>wordReviewCard(x)).join(''):'<div class="empty" style="margin-top:18px"><b>今天没有已记录的到期错词。</b>先做百词斩到期复习；这里仅追踪你手动添加的困难项。</div>'}<p class="inline-note">默认建议：忘了→明天；费力→2天后；轻松→逐步延长到3/7/14/30天。只是可调整起点，研究不证明它对你最优。</p></section></div>${l.entries.length?`<details><summary>所有错词索引与下次日期（${l.entries.length}条）</summary><div class="detail-body"><div class="table-wrap"><table><thead><tr><th>词</th><th>下次</th><th>结果</th><th>操作</th></tr></thead><tbody>${l.entries.map(x=>`<tr><td>${escapeHTML(x.term)}</td><td>${x.due}</td><td>${{new:'待测',forgot:'忘了',hard:'费力',easy:'轻松'}[x.last]}</td><td><button class="quiet" data-word-delete="${x.id}">删除</button></td></tr>`).join('')}</tbody></table></div></div></details>`:''}<section class="panel" style="margin-top:22px"><h2>这里“更科学”的含义</h2><p style="margin-top:12px">用主动回忆、分散练习、及时核对和新题迁移替代只看熟悉感；用抽样表现调整新词与复习量。没有把某个App、纸笔形式或固定分钟数说成最优。</p><div class="actions"><a href="${STUDY_RESOURCES.retrieval.url}" target="_blank" rel="noopener noreferrer">主动回忆：原始研究</a><a href="${STUDY_RESOURCES.distributed.url}" target="_blank" rel="noopener noreferrer">分散练习：研究综述</a></div></section>`}
function wordReviewCard(x){return`<div class="word-card"><div class="word-card-head"><b>${escapeHTML(x.term)}</b><small>到期 ${x.due}</small></div><details><summary>我先回忆过了，展开答案</summary><div class="detail-body"><p>${escapeHTML(x.meaning)}</p><p>${escapeHTML(x.example)}</p><div class="actions"><button class="secondary" data-word-review="${x.id}" data-recall="forgot">忘了 · 明天</button><button class="secondary" data-word-review="${x.id}" data-recall="hard">费力 · 2天后</button><button class="soft" data-word-review="${x.id}" data-recall="easy">轻松 · 拉开间隔</button></div></div></details></div>`}
function bindDailyForms(){
 $('#vocab-settings-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{state=sanitize({...state,learning:{...state.learning,seen:Number(f.get('seen')),newLimit:Number(f.get('newLimit')),phase:f.get('phase')}});const ok=save();render();if(ok)toast('已保存你的真实词汇进度。')}catch(err){toast(err.message)}});
 $('#paper-word-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const entry={id:'word_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),term:String(f.get('term')).trim(),meaning:f.get('meaning'),example:f.get('example'),due:f.get('due'),streak:0,last:'new'};try{state=sanitize({...state,learning:{...state.learning,entries:[...state.learning.entries,entry]}});const ok=save();render();if(ok)toast('错词已保存，下次按日期回忆。')}catch(err){toast(err.message)}})
}
function handleDailyClick(e){const el=e.target.closest('button');if(!el)return;if(el.dataset.openTask)openTask(el.dataset.openTask);if(el.dataset.selectDay!==undefined){selectedDay=Number(el.dataset.selectDay);render()}if(el.dataset.dailyWeek){selectedWeek=Number(el.dataset.dailyWeek);selectedDay=0;render()}if(el.dataset.wordDelete){const id=el.dataset.wordDelete;askConfirm('删除这条错词？','仅删除当前浏览器中的这一条索引。纸书和百词斩中的记录不会改变。',()=>{state.learning.entries=state.learning.entries.filter(x=>x.id!==id);const ok=save();render();if(ok)toast('错词索引已删除。')})}if(el.dataset.wordReview){const x=state.learning.entries.find(x=>x.id===el.dataset.wordReview),result=el.dataset.recall;if(x&&['forgot','hard','easy'].includes(result)){x.last=result;x.streak=result==='easy'?Math.min(100,x.streak+1):0;const gap=result==='forgot'?1:result==='hard'?2:[3,7,14,30][Math.min(3,x.streak-1)];x.due=plusDays(today(),gap);const ok=save();render();if(ok)toast('已记录回忆结果；下次 '+x.due+'。')}}const action=el.dataset.action;if(action==='back-today'){selectedWeek=currentWeek();selectedDay=dayIndexFor(selectedWeek);render()}if(action==='toggle-week-days'){showAllDays=!showAllDays;render()}if(action==='close-task'){$('#task-dialog').close();openTaskId=null}if(action==='save-task-note'){if(saveTaskNote())toast('任务产物/笔记已保存。')}if(action==='complete-open-task'&&openTaskId){saveTaskNote();state.dayChecks[openTaskId]=!state.dayChecks[openTaskId];const ok=save();const id=openTaskId;render();openTask(id);if(ok)toast(state.dayChecks[id]?'本块已完成。下次仍需复測验证。':'已取消完成标记。')}if(action==='next-task'&&openTaskId){saveTaskNote();const t=taskById(openTaskId);if(!t)return;const all=dailyPlan(t.w,t.mode).flat(),idx=all.findIndex(x=>x.id===openTaskId),next=all[idx+1];if(next){selectedWeek=next.w;selectedDay=next.d;render();openTask(next.id)}else{$('#task-dialog').close();openTaskId=null;toast('这周到这里，留下复盘后休息。')}}}
document.addEventListener('click',handleDailyClick);
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.dailyCheck){const t=taskById(el.dataset.dailyCheck);if(!t)return;state.dayChecks[t.id]=el.checked;const ok=save();render();if(ok&&el.checked)toast('已完成本次产物。复测成功才代表更稳了。')}});
STUDY_RESOURCES.ready={title:'IELTS Ready免费注册资源',url:'https://takeielts.britishcouncil.org/en-gb/ielts-ready-preparation-made-easy',type:'官方 · 需免费注册',note:'页面介绍免费practice tests；未登录核实各科数量和账户内内容，不保证已准备6套完整卷。'};
STUDY_RESOURCES.familiar={title:'官方机考熟悉测试 · 选择Academic',url:'https://takeielts.britishcouncil.org/prepare/ielts-free-practice-mock-tests/ielts-familiarisation-test',type:'官方 · 免费入口',note:'提供听读结果，不给写作/口语评分。已核查介绍页，未实际运行完整测试。'};
const originalTaskMaterials=taskMaterials;
taskMaterials=function(t){if(['ltest','rtest','mock'].includes(t.kind))return[resourceLink('familiar'),resourceLink('c20'),resourceLink('ready')];return originalTaskMaterials(t)};

function methodResourceBlock(k){const keys={L:['lpdf','laudio1'],R:['rpdf'],W:['wpdf','wband'],S:['spdf','sband','svideo'],V:['bcz','book','bookcheck']}[k];return `<section class="panel" style="margin-bottom:20px"><h2>这一科，直接打开材料</h2><div class="quick-links">${keys.map(key=>`<a href="${escapeHTML(STUDY_RESOURCES[key].url)}" target="_blank" rel="noopener noreferrer">${STUDY_RESOURCES[key].title}<small>${STUDY_RESOURCES[key].type}</small></a>`).join('')}</div></section>`}

function lSelection(w){if([3,9].includes(w))return{label:'Multiple Choice：仅2题p8，原文p9，答案p10',page:8,audio:'laudio2',short:true};if([5,11].includes(w))return{label:'Part2地图：题p26，原文p27，答案p28',page:26,audio:'laudio7'};if([6,14].includes(w))return{label:'Part3观点/意向匹配：题p18，原文p19–20，答案p21',page:18,audio:'laudio5'};if([7,10,13,15].includes(w))return{label:'Part2艺术中心笔记填空：题p29–30，原文p31–32，答案p33',page:29,audio:'laudio8'};return{label:'Form Completion：题p3，原文p4–6，答案p7',page:3,audio:'laudio1'}}
STUDY_RESOURCES.laudio2={title:'Multiple Choice · 2题录音MP3',url:'https://ielts.org/cdn/ielts-sample-tests/ielts-listening/ielts-listening-sample-task-2-multiple-choice.mp3',type:'官方音频',note:'从官方PDF实际链接核实出处，未验证播放；直链不能打开时用PDFp9录音入口。'};
STUDY_RESOURCES.laudio5={title:'Part3 Matching · 选课意向录音MP3',url:'https://ielts.org/cdn/ielts-sample-tests/ielts-listening/ielts-listening-sample-task-5-matching.mp3',type:'官方音频',note:'从官方PDF实际链接核实出处，未验证播放；打不开时用PDFp19录音入口。'};
STUDY_RESOURCES.laudio7={title:'Part2地图 · 图书馆平面图录音MP3',url:'https://ielts.org/cdn/ielts-sample-tests/ielts-listening/ielts-listening-sample-task-7-plan-map-diagram-labelling.mp3',type:'官方音频',note:'从官方PDF实际链接核实出处，未验证播放；打不开时用PDFp27录音入口。'};
